// Give every case real state notifications and a running KNX transport without Wi-Fi.
static void reset() {
  strip = Strip{};
  strip.getMainSegment().colors[0] = RGBW32(120,80,40,77);
  strip.getMainSegment().mode = 50;
  Segment::renderedColor = RGBW32(9,9,9,9);
  bri = 100; briOld16 = briT16 = uint16_t(bri) << 8;
  currentPreset = 0; stateChanged = false;
  setValuesFromSegment(0);
  stateUpdates = colorUpdates = publishes = colorWrites = brightnessWrites = modeWrites = 0;
  interfaceUpdateCallMode = CALL_MODE_INIT;
  notificationModes.clear(); sentDatagrams.clear(); failSend = false;
  testMillis = 1000;
  nightlightActive = nightlightActiveOld = transitionActive = false;
  KNX = KnxIpCore{}; KNX._running = true; KNX.setIndividualAddress(0x1101);
}

// Register real callbacks; these are the documented central default addresses.
static void configure(KnxIpUsermod& m, bool channels = true) {
  m.enabled = true;
  m.GA_IN_RGB = 0x090D; m.GA_IN_HSV = 0x090E; m.GA_IN_RGBW = 0x090F;
  m.GA_IN_RGB_REL = 0x091A; m.GA_IN_HSV_REL = 0x091B; m.GA_IN_RGBW_REL = 0x091C;
  m.GA_IN_BRI_REL = 0x0803; m.GA_IN_H_REL = 0x0916; m.GA_IN_S_REL = 0x0917;
  m.GA_IN_V_REL = 0x0918; m.GA_IN_FX_REL = 0x0919;
  m.registerColorHandlers();
  if (channels) {
    m.GA_OUT_R = 0x1101; m.GA_OUT_G = 0x1102; m.GA_OUT_B = 0x1103; m.GA_OUT_W = 0x1104;
  }
  m.GA_OUT_RGB = 0x110D; m.GA_OUT_HSV = 0x110E; m.GA_OUT_RGBW = 0x110F;
  m.GA_OUT_H = 0x1108; m.GA_OUT_S = 0x1109; m.GA_OUT_V = 0x110A;
  m.GA_OUT_FX = 0x110B; m.GA_OUT_BRI = 0x1002; m.GA_OUT_PWR = 0x1001;
  KNX.addGroupObject(m.GA_OUT_PWR,DptMain::DPT_1xx,true,false);
}

// Encode fixed KNXnet/IP input vectors, independently of production TX encoding.
static void receive(uint16_t ga, std::initializer_list<uint8_t> bytes, bool embedded = false) {
  std::vector<uint8_t> frame = {6,16,5,48,0,0,41,0,188,224,17,2,
    uint8_t(ga>>8),uint8_t(ga),uint8_t(embedded?1:1+bytes.size()),0,128};
  if (embedded) frame.back() |= *bytes.begin();
  else frame.insert(frame.end(),bytes.begin(),bytes.end());
  frame[5] = uint8_t(frame.size());
  KNX._handleIncoming(frame.data(),int(frame.size()));
}

// Inspect actual UDP datagrams captured after production DPT/cEMI encoding.
static const std::vector<uint8_t>* packet(uint16_t ga) {
  for (const auto& p : sentDatagrams) {
    if (p.size() >= 17 && ((uint16_t(p[12])<<8)|p[13]) == ga) return &p;
  }
  return nullptr;
}
static bool payload(uint16_t ga, std::initializer_list<uint8_t> expected) {
  const auto* p = packet(ga);
  return p && p->size() == 17+expected.size() &&
    std::equal(expected.begin(),expected.end(),p->begin()+17);
}

// Execute the real scheduler and deadline service, not a publication-call counter.
static void flush(KnxIpUsermod& m) {
  testMillis += m.txRateLimitMs;
  m.processPendingState();
}
static void prime(KnxIpUsermod& m) {
  m.scheduleStatePublish(); flush(m); sentDatagrams.clear();
}

static void testColorPersistence() {
  reset(); KnxIpUsermod m; configure(m); prime(m);
  receive(m.GA_IN_RGB_REL,{8,15,7});
  check(strip.getMainSegment().colors[0] == RGBW32(120,83,37,77),"RGB relative survives real state update");
  check(colPri[1] == 83 && colPri[2] == 37,"legacy GUI fields follow RGB relative");
  check(stateUpdates == 1 && interfaceUpdateCallMode == CALL_MODE_DIRECT_CHANGE,"real update notification mode");
  flush(m); check(payload(m.GA_OUT_RGB,{120,83,37}),"RGB relative is actually published");

  reset(); KnxIpUsermod n; configure(n); prime(n);
  receive(n.GA_IN_RGBW,{1,2,3,4,0,0});
  check(strip.getMainSegment().colors[0] == RGBW32(1,2,3,4),"RGBW write survives real state update");
  flush(n); check(payload(n.GA_OUT_RGBW,{1,2,3,4,0,0}),"RGBW output encoding");

  reset(); KnxIpUsermod w; configure(w); prime(w);
  w.onKnxWhite(80);
  check(strip.getMainSegment().colors[0] == RGBW32(120,80,40,80),"absolute white survives update");
  w.onKnxWWRel(15);
  check(W(strip.getMainSegment().colors[0]) > 80,"warm relative survives update");
}

static void testOutputModes() {
  for (uint8_t mode : {uint8_t(0),uint8_t(1),uint8_t(2)}) {
    reset(); KnxIpUsermod m; configure(m,false); m.colorOutMode = mode; prime(m);
    receive(m.GA_IN_HSV,{85,255,255}); flush(m);
    check((packet(m.GA_OUT_RGB)!=nullptr) == (mode!=0),"composite-only GA configuration publishes by mode");
    check((packet(m.GA_OUT_H)!=nullptr) == (mode!=1),"individual HSV publishes in channel modes");
    if (mode!=0) {
      check(payload(m.GA_OUT_RGB,{0,255,0}),"composite RGB independent of channel GAs");
      check(payload(m.GA_OUT_HSV,{85,255,255}),"composite HSV payload");
    }
    if (mode!=1) check(payload(m.GA_OUT_H,{85}),"individual H payload with only HSV outputs");
  }
}

static void testMainSegment() {
  reset(); strip.main=1; strip.firstSelected=0;
  strip.segments[1].colors[0]=RGBW32(10,20,30,99); strip.segments[1].mode=20; strip.segments[1].cct=200;
  const auto unrelated = strip.segments[0].colors[0];
  KnxIpUsermod m; configure(m); prime(m);
  receive(m.GA_IN_HSV,{170,255,128});
  check(strip.segments[1].colors[0]==RGBW32(0,0,128,99),"HSV targets main segment 1");
  check(strip.segments[0].colors[0]==unrelated,"unrelated selected segment untouched");
  check(colPri[2]==128 && colPri[3]==99 && notifiedColor[3]==99,"GUI and notification use targeted main segment");
  flush(m); check(payload(m.GA_OUT_RGBW,{0,0,128,99,0,0}),"feedback uses same main segment");
  sentDatagrams.clear(); effectCurrent = 99;
  receive(m.GA_IN_FX_REL,{9},true); flush(m);
  check(strip.segments[1].mode==30 && strip.segments[0].mode==50,"relative effect reads main mode");
  check(payload(m.GA_OUT_FX,{30}),"effect feedback ignores other selected segment");
  m.onKnxCct(6500);
  check(strip.segments[1].cct==255 && strip.segments[0].cct==127,"CCT targets main segment");
  m.GA_OUT_CCT=0x1105; sentDatagrams.clear(); flush(m);
  check(payload(m.GA_OUT_CCT,{0x19,0x64}),"CCT feedback is main-segment Kelvin in network order");
  strip.segments[1].colors[0]=RGBW32(10,20,30,128); strip.segments[1].cct=0;
  m.onKnxWWRel(15);
  check(strip.segments[1].colors[0]==RGBW32(10,20,30,131) && strip.segments[1].cct==0,
        "warm/cold decomposition uses main segment");
  check(strip.segments[0].colors[0]==unrelated && strip.segments[0].cct==127,"white edits leave segment zero untouched");

  // UI changes to the main segment selector must also switch the status source.
  sentDatagrams.clear(); strip.main=0; m.scheduleStatePublish(); flush(m);
  check(payload(m.GA_OUT_RGBW,{120,80,40,77,0,0}) && payload(m.GA_OUT_FX,{50}),
        "runtime main-segment change refreshes central feedback");
}

static void testEnhancedDimming() {
  reset(); KnxIpUsermod m; configure(m); prime(m);
  KNX.setCommunicationEnhancement(true,1,0,700);
  receive(m.GA_IN_BRI_REL,{15},true); testMillis+=20;
  receive(m.GA_IN_BRI_REL,{14},true);
  check(bri==111,"enhancement preserves distinct rapid DPT3 steps");
  testMillis+=20; receive(m.GA_IN_BRI_REL,{8},true);
  check(bri==111 && stateUpdates==2,"increase STOP reaches handler without changing state");
  testMillis+=20; receive(m.GA_IN_BRI_REL,{7},true);
  check(bri==108,"decrease is not treated as a bit toggle");
  testMillis+=20; receive(m.GA_IN_BRI_REL,{0},true);
  check(bri==108 && stateUpdates==3,"decrease STOP adds no step");
  const auto rx = KNX.rxPackets();
  testMillis+=20; receive(m.GA_IN_BRI_REL,{7},true);
  check(bri==108 && KNX.rxPackets()==rx,"identical routing repeat remains deduplicated");
  unsigned bitCalls=0;
  KNX.addGroupObject(0x0801,DptMain::DPT_1xx,false,true);
  KNX.onGroup(0x0801,[&](uint16_t,DptMain,KnxService,const uint8_t*,uint8_t){++bitCalls;});
  receive(0x0801,{0},true); testMillis+=20; receive(0x0801,{1},true);
  check(bitCalls==1,"DPT1 toggle throttle retained");
}

static void testCoalescingAndStops() {
  reset(); KnxIpUsermod m; configure(m); prime(m);
  receive(m.GA_IN_HSV,{0,255,255});
  testMillis+=100; m.processPendingState(); check(sentDatagrams.empty(),"no early publish");
  receive(m.GA_IN_HSV,{85,255,255});
  testMillis+=100; m.processPendingState();
  check(payload(m.GA_OUT_RGB,{0,255,0}),"coalescing publishes latest target at original deadline");
  sentDatagrams.clear(); const auto updates=stateUpdates;
  for (auto stop : {uint8_t(0),uint8_t(8)}) receive(m.GA_IN_BRI_REL,{stop},true);
  flush(m); check(sentDatagrams.empty() && stateUpdates==updates,"idle STOP emits neither update nor UDP packet");
  reset(); KnxIpUsermod first; configure(first,false);
  receive(first.GA_IN_HSV,{0,255,255}); flush(first);
  check(payload(first.GA_OUT_RGB,{255,0,0}),"first command is not swallowed by snapshot initialization");
}

// Existing one-argument callers keep selected-segment behavior; only explicit
// callers opt into another synchronization source. Legacy colorUpdated is intact.
static void testCoreCompatibility() {
  reset(); strip.main=1; strip.firstSelected=0;
  strip.segments[1].colors[0]=RGBW32(1,2,3,4); strip.segments[1].mode=9;
  stateChanged=true; stateUpdated(CALL_MODE_DIRECT_CHANGE);
  check(colPri[0]==120 && effectCurrent==50,"one-argument stateUpdated retains selected source");
  stateChanged=true; stateUpdated(CALL_MODE_DIRECT_CHANGE,1);
  check(colPri[0]==1 && colPri[3]==4 && effectCurrent==9,"explicit source synchronizes before notifications");
  check(notifiedColor[3]==4 && notifiedEffect==9,"notification sees explicit source values");
  stateUpdated(CALL_MODE_DIRECT_CHANGE,255);
  check(colPri[0]==120,"invalid source safely falls back to first selected segment");
  colPri[0]=11; colPri[1]=12; colPri[2]=13; colPri[3]=14;
  colorUpdated(CALL_MODE_DIRECT_CHANGE);
  check(strip.segments[0].colors[0]==RGBW32(11,12,13,14) &&
        strip.segments[1].colors[0]==RGBW32(11,12,13,14),"legacy colorUpdated still applies to all selected segments");
}

static void testFeedbackAndGuards() {
  reset(); KnxIpUsermod m; configure(m); prime(m);
  receive(m.GA_IN_BRI_REL,{15},true); flush(m);
  check(bri==103 && payload(m.GA_OUT_BRI,{102}),"DPT5 brightness feedback preserves percent quantization");
  sentDatagrams.clear(); receive(m.GA_IN_BRI_REL,{1},true); flush(m);
  const auto* off=packet(m.GA_OUT_PWR);
  check(bri==0 && off && off->size()==17 && (*off)[16]==0x80,"power off uses embedded DPT1 bit");
  sentDatagrams.clear(); const auto before=strip.getMainSegment().colors[0];
  const auto calls=stateUpdates;
  receive(m.GA_IN_HSV,{85,255});
  check(strip.getMainSegment().colors[0]==before && stateUpdates==calls,"short HSV payload rejected through actual routing");
  const uint8_t truncated[]={6,16,5,48,0,30};
  const auto errors=KNX.rxErrors(); KNX._handleIncoming(truncated,sizeof(truncated));
  check(KNX.rxErrors()==errors+1 && stateUpdates==calls,"truncated routing frame rejected");
  m.enabled=false; m.onKnxRGB(4,5,6); flush(m);
  check(sentDatagrams.empty(),"disabled publisher sends no datagram");

  reset(); KnxIpUsermod autoOn; configure(autoOn); bri=0; briOld16=briT16=0; prime(autoOn);
  receive(autoOn.GA_IN_HSV,{0,0,0}); flush(autoOn);
  check(bri==0 && W(strip.getMainSegment().colors[0])==77,"real update keeps black HSV off and retains W");
  autoOn.autoEnableBrightness=91; sentDatagrams.clear();
  receive(autoOn.GA_IN_HSV,{0,255,128}); flush(autoOn);
  check(bri==91 && briT16==(uint16_t(91)<<8),"auto-enable reaches real brightness update");
  const auto* on=packet(autoOn.GA_OUT_PWR);
  check(on && on->size()==17 && (*on)[16]==0x81,"auto-enable publishes true DPT1 bit");

  // STOP cannot cancel a prior command's already scheduled feedback.
  sentDatagrams.clear(); receive(autoOn.GA_IN_HSV,{170,255,128});
  receive(autoOn.GA_IN_BRI_REL,{8},true); flush(autoOn);
  check(payload(autoOn.GA_OUT_RGB,{0,0,128}),"pending legitimate color feedback survives STOP");
}

int main() {
  testColorPersistence(); testOutputModes(); testMainSegment(); testEnhancedDimming(); testCoalescingAndStops();
  testCoreCompatibility(); testFeedbackAndGuards();
  std::printf("KNX/WLED production integration: %u checks, %u failures\n",checks,failures);
  return failures?1:0;
}
